n,m=map(int,input().split())
g=[[] for _ in range(n+1)]
for _ in range(m):
 a,b=map(int,input().split());g[a].append(b);g[b].append(a)
seen=set();ans=0
for s in range(1,n+1):
 if s in seen: continue
 ans+=1;seen.add(s);q=[s]
